//! Shared OAuth infrastructure: built-in credentials, callback server, landing pages.//!//! Every OAuth flow in the codebase (WASM tool auth, MCP server auth, NEAR AI login)//! uses the same callback port, landing page, and listener logic from this module.//!//! # Built-in Credentials//!//! Many CLI tools (gcloud, rclone, gdrive) ship with default OAuth credentials//! so users don't need to register their own OAuth app. Google explicitly//! documents that client_secret for "Desktop App" / "Installed App" types//! is NOT actually secret.//!//! Default credentials are hardcoded below. They can be overridden at://!//! - **Compile time**: Set IRONCLAW_GOOGLE_CLIENT_ID / IRONCLAW_GOOGLE_CLIENT_SECRET//!   env vars before building to replace the hardcoded defaults.//! - **Runtime**: Users can set GOOGLE_OAUTH_CLIENT_ID / GOOGLE_OAUTH_CLIENT_SECRET//!   env vars, which take priority over built-in defaults.use std::collections::HashMap;use std::sync::Arc;use std::time::Duration;use base64::{Engine, engine::general_purpose::URL_SAFE_NO_PAD};use rand::RngCore;use sha2::{Digest, Sha256};use tokio::sync::RwLock;use crate::secrets::{CreateSecretParams, SecretsStore};// ── Built-in credentials ────────────────────────────────────────────────pub struct OAuthCredentials {    pub client_id: &'static str,    pub client_secret: &'static str,}/// Google OAuth "Desktop App" credentials, shared across all Google tools./// Compile-time env vars override the hardcoded defaults below.const GOOGLE_CLIENT_ID: &str = match option_env!("IRONCLAW_GOOGLE_CLIENT_ID") {    Some(v) => v,    None => "564604149681-efo25d43rs85v0tibdepsmdv5dsrhhr0.apps.googleusercontent.com",};const GOOGLE_CLIENT_SECRET: &str = match option_env!("IRONCLAW_GOOGLE_CLIENT_SECRET") {    Some(v) => v,    None => "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",};/// Returns built-in OAuth credentials for a provider, keyed by secret_name.////// The secret_name comes from the tool's capabilities.json `auth.secret_name` field./// Returns `None` if no built-in credentials are configured for that provider.pub fn builtin_credentials(secret_name: &str) -> Option<OAuthCredentials> {    match secret_name {        "google_oauth_token" => Some(OAuthCredentials {            client_id: GOOGLE_CLIENT_ID,            client_secret: GOOGLE_CLIENT_SECRET,        }),        _ => None,    }}// ── Shared callback server ──────────────────────────────────────────────// Core OAuth callback infrastructure is defined in `crate::llm::oauth_helpers`// and re-exported here for backward compatibility.pub use crate::llm::oauth_helpers::{    OAUTH_CALLBACK_PORT, OAuthCallbackError, bind_callback_listener, callback_host, callback_url,    is_loopback_host, landing_html, wait_for_callback,};// ── Shared OAuth flow steps ─────────────────────────────────────────/// Response from the OAuth token exchange.pub struct OAuthTokenResponse {    pub access_token: String,    pub refresh_token: Option<String>,    pub expires_in: Option<u64>,}/// Result of building an OAuth 2.0 authorization URL.pub struct OAuthUrlResult {    /// The full authorization URL to redirect the user to.    pub url: String,    /// PKCE code verifier (must be sent with the token exchange request).    pub code_verifier: Option<String>,    /// Random state parameter for CSRF protection (must be validated in callback).    pub state: String,}/// Build an OAuth 2.0 authorization URL with optional PKCE and CSRF state.////// Returns an `OAuthUrlResult` containing the authorization URL, optional PKCE/// code verifier, and a random `state` parameter for CSRF protection. The caller/// must validate the `state` value in the callback before exchanging the code.pub fn build_oauth_url(    authorization_url: &str,    client_id: &str,    redirect_uri: &str,    scopes: &[String],    use_pkce: bool,    extra_params: &HashMap<String, String>,) -> OAuthUrlResult {    // Generate PKCE verifier and challenge    let (code_verifier, code_challenge) = if use_pkce {        let mut verifier_bytes = [0u8; 32];        rand::rngs::OsRng.fill_bytes(&mut verifier_bytes);        let verifier = URL_SAFE_NO_PAD.encode(verifier_bytes);        let mut hasher = Sha256::new();        hasher.update(verifier.as_bytes());        let challenge = URL_SAFE_NO_PAD.encode(hasher.finalize());        (Some(verifier), Some(challenge))    } else {        (None, None)    };    // Generate random state for CSRF protection    let mut state_bytes = [0u8; 32];    rand::rngs::OsRng.fill_bytes(&mut state_bytes);    let state = URL_SAFE_NO_PAD.encode(state_bytes);    // Build authorization URL    let mut auth_url = format!(        "{}?client_id={}&response_type=code&redirect_uri={}&state={}",        authorization_url,        urlencoding::encode(client_id),        urlencoding::encode(redirect_uri),        urlencoding::encode(&state),    );    if !scopes.is_empty() {        auth_url.push_str(&format!(            "&scope={}",            urlencoding::encode(&scopes.join(" "))        ));    }    if let Some(ref challenge) = code_challenge {        auth_url.push_str(&format!(            "&code_challenge={}&code_challenge_method=S256",            challenge        ));    }    for (key, value) in extra_params {        auth_url.push_str(&format!(            "&{}={}",            urlencoding::encode(key),            urlencoding::encode(value)        ));    }    OAuthUrlResult {        url: auth_url,        code_verifier,        state,    }}/// Exchange an OAuth authorization code for tokens.////// POSTs to `token_url` with the authorization code and optional PKCE verifier./// If `client_secret` is provided, uses HTTP Basic auth; otherwise includes/// `client_id` in the form body (for public clients).pub async fn exchange_oauth_code(    token_url: &str,    client_id: &str,    client_secret: Option<&str>,    code: &str,    redirect_uri: &str,    code_verifier: Option<&str>,    access_token_field: &str,) -> Result<OAuthTokenResponse, OAuthCallbackError> {    // Delegates to exchange_oauth_code_with_resource with resource=None.    // Non-MCP OAuth flows don't need the RFC 8707 resource parameter.    exchange_oauth_code_with_resource(        token_url,        client_id,        client_secret,        code,        redirect_uri,        code_verifier,        access_token_field,        None,    )    .await}/// Exchange an OAuth authorization code for tokens, with optional RFC 8707 `resource` parameter.////// The `resource` parameter scopes the issued token to a specific server (used by MCP OAuth).#[allow(clippy::too_many_arguments)]pub async fn exchange_oauth_code_with_resource(    token_url: &str,    client_id: &str,    client_secret: Option<&str>,    code: &str,    redirect_uri: &str,    code_verifier: Option<&str>,    access_token_field: &str,    resource: Option<&str>,) -> Result<OAuthTokenResponse, OAuthCallbackError> {    let client = reqwest::Client::new();    let mut token_params = vec![        ("grant_type", "authorization_code".to_string()),        ("code", code.to_string()),        ("redirect_uri", redirect_uri.to_string()),    ];    if let Some(verifier) = code_verifier {        token_params.push(("code_verifier", verifier.to_string()));    }    // RFC 8707: include the `resource` parameter so the authorization server    // scopes the issued token to the specific MCP server (protected resource).    if let Some(resource) = resource {        token_params.push(("resource", resource.to_string()));    }    let mut request = client.post(token_url);    if let Some(secret) = client_secret {        request = request.basic_auth(client_id, Some(secret));    } else {        token_params.push(("client_id", client_id.to_string()));    }    let token_response = request        .form(&token_params)        .send()        .await        .map_err(|e| OAuthCallbackError::Io(format!("Token exchange request failed: {}", e)))?;    if !token_response.status().is_success() {        let status = token_response.status();        let body = token_response.text().await.unwrap_or_default();        return Err(OAuthCallbackError::Io(format!(            "Token exchange failed: {} - {}",            status, body        )));    }    let token_data: serde_json::Value = token_response        .json()        .await        .map_err(|e| OAuthCallbackError::Io(format!("Failed to parse token response: {}", e)))?;    let access_token = token_data        .get(access_token_field)        .and_then(|v| v.as_str())        .ok_or_else(|| {            // Log only the field names present, not values (which may contain tokens)            let fields: Vec<&str> = token_data                .as_object()                .map(|o| o.keys().map(|k| k.as_str()).collect())                .unwrap_or_default();            OAuthCallbackError::Io(format!(                "No '{}' field in token response (fields present: {:?})",                access_token_field, fields            ))        })?        .to_string();    let refresh_token = token_data        .get("refresh_token")        .and_then(|v| v.as_str())        .map(String::from);    let expires_in = token_data.get("expires_in").and_then(|v| v.as_u64());    Ok(OAuthTokenResponse {        access_token,        refresh_token,        expires_in,    })}/// Store OAuth tokens (access + refresh) in the secrets store.////// Also stores the granted scopes as `{secret_name}_scopes` so that scope
/// expansion can be detected on subsequent activations.#[allow(clippy::too_many_arguments)]pub async fn store_oauth_tokens(    store: &(dyn SecretsStore + Send + Sync),    user_id: &str,    secret_name: &str,    provider: Option<&str>,    access_token: &str,    refresh_token: Option<&str>,    expires_in: Option<u64>,    scopes: &[String],) -> Result<(), OAuthCallbackError> {    let mut params = CreateSecretParams::new(secret_name, access_token);    if let Some(prov) = provider {        params = params.with_provider(prov);    }    if let Some(secs) = expires_in {        let expires_at = chrono::Utc::now() + chrono::Duration::seconds(secs as i64);        params = params.with_expiry(expires_at);    }    store        .create(user_id, params)        .await        .map_err(|e| OAuthCallbackError::Io(format!("Failed to save token: {}", e)))?;    // Store refresh token separately (no expiry, it's long-lived)    if let Some(rt) = refresh_token {        let refresh_name = format!("{}_refresh_token", secret_name);        let mut refresh_params = CreateSecretParams::new(&refresh_name, rt);        if let Some(prov) = provider {            refresh_params = refresh_params.with_provider(prov);        }        store            .create(user_id, refresh_params)            .await            .map_err(|e| OAuthCallbackError::Io(format!("Failed to save refresh token: {}", e)))?;    }    // Store granted scopes for scope expansion detection    if !scopes.is_empty() {        let scopes_name = format!("{}_scopes", secret_name);        let scopes_value = scopes.join(" ");        let scopes_params = CreateSecretParams::new(&scopes_name, &scopes_value);        // Best-effort: scope tracking failure shouldn't block auth        let _ = store.create(user_id, scopes_params).await;    }    Ok(())}/// Validate an OAuth token against a tool's validation endpoint.////// Sends a request to the configured endpoint with the token as a Bearer header./// Returns `Ok(())` if the response status matches the expected success status,/// or an error with details if validation fails (wrong account, expired token, etc.).pub async fn validate_oauth_token(    token: &str,    validation: &crate::tools::wasm::ValidationEndpointSchema,) -> Result<(), OAuthCallbackError> {    let client = reqwest::Client::builder()        .timeout(Duration::from_secs(10))        .build()        .map_err(|e| OAuthCallbackError::Io(format!("Failed to build HTTP client: {}", e)))?;    let request = match validation.method.to_uppercase().as_str() {        "POST" => client.post(&validation.url),        _ => client.get(&validation.url),    };    let mut request = request.header("Authorization", format!("Bearer {}", token));    // Add custom headers from the validation schema (e.g., Notion-Version)    for (key, value) in &validation.headers {        request = request.header(key, value);    }    let response = request        .send()        .await        .map_err(|e| OAuthCallbackError::Io(format!("Validation request failed: {}", e)))?;    if response.status().as_u16() == validation.success_status {        Ok(())    } else {        let status = response.status();        let body = response.text().await.unwrap_or_default();        let truncated: String = if body.len() > 200 {            let mut end = 200;            while end > 0 && !body.is_char_boundary(end) {                end -= 1;            }            format!("{}...", &body[..end])        } else {            body        };        Err(OAuthCallbackError::Io(format!(            "Token validation failed: HTTP {} (expected {}): {}",            status, validation.success_status, truncated        )))    }}// ── Gateway callback support ─────────────────────────────────────────/// State for an in-progress OAuth flow, keyed by CSRF `state` parameter.////// Created by `start_wasm_oauth()` and consumed by the web gateway's/// `/oauth/callback` handler when running in hosted mode.pub struct PendingOAuthFlow {    /// Extension name (e.g., "google_calendar").    pub extension_name: String,    /// Human-readable display name (e.g., "Google Calendar").    pub display_name: String,    /// OAuth token exchange URL.    pub token_url: String,    /// OAuth client ID.    pub client_id: String,    /// OAuth client secret (optional for PKCE-only flows).    pub client_secret: Option<String>,    /// The redirect_uri used in the authorization request.    pub redirect_uri: String,    /// PKCE code verifier (must match the code_challenge sent in the auth URL).    pub code_verifier: Option<String>,    /// Field name in token response containing the access token.    pub access_token_field: String,    /// Secret name for storage (e.g., "google_oauth_token").    pub secret_name: String,    /// Provider hint (e.g., "google").    pub provider: Option<String>,    /// Token validation endpoint (optional).    pub validation_endpoint: Option<crate::tools::wasm::ValidationEndpointSchema>,    /// Scopes that were requested.    pub scopes: Vec<String>,    /// User ID for secret storage.    pub user_id: String,    /// Secrets store reference for token persistence.    pub secrets: Arc<dyn SecretsStore + Send + Sync>,    /// SSE broadcast sender for notifying the web UI.    pub sse_sender: Option<tokio::sync::broadcast::Sender<crate::channels::web::types::SseEvent>>,    /// Gateway auth token for authenticating with the platform token exchange proxy.    pub gateway_token: Option<String>,    /// RFC 8707 resource parameter (MCP OAuth only).    /// Sent during token exchange to scope the token to a specific MCP server.    pub resource: Option<String>,    /// Secret name for persisting the client ID (MCP OAuth only).    /// Needed so token refresh can find the client_id after the session ends.    pub client_id_secret_name: Option<String>,    /// When this flow was created (for expiry).    pub created_at: std::time::Instant,}impl std::fmt::Debug for PendingOAuthFlow {    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {        f.debug_struct("PendingOAuthFlow")            .field("extension_name", &self.extension_name)            .field("display_name", &self.display_name)            .field("secret_name", &self.secret_name)            .field("created_at", &self.created_at)            .finish_non_exhaustive()    }}/// Thread-safe registry of pending OAuth flows, keyed by CSRF `state` parameter.pub type PendingOAuthRegistry = Arc<RwLock<HashMap<String, PendingOAuthFlow>>>;/// Create a new empty pending OAuth flow registry.pub fn new_pending_oauth_registry() -> PendingOAuthRegistry {    Arc::new(RwLock::new(HashMap::new()))}/// Returns `true` if OAuth callbacks should be routed through the web gateway/// instead of the local TCP listener.////// This is the case when `IRONCLAW_OAUTH_CALLBACK_URL` is set to a non-loopback/// URL, meaning the user's browser will redirect to a hosted gateway rather than/// localhost.pub fn use_gateway_callback() -> bool {    std::env::var("IRONCLAW_OAUTH_CALLBACK_URL")        .ok()        .filter(|v| !v.is_empty())        .map(|raw| {            url::Url::parse(&raw)                .ok()                .and_then(|u| u.host_str().map(String::from))                .map(|host| !is_loopback_host(&host))                .unwrap_or(false)        })        .unwrap_or(false)}/// Maximum age for pending OAuth flows (5 minutes, matching TCP listener timeout).pub const OAUTH_FLOW_EXPIRY: Duration = Duration::from_secs(300);/// Remove expired flows from the registry.////// Called when inserting new flows to prevent accumulation from abandoned/// OAuth attempts.pub async fn sweep_expired_flows(registry: &PendingOAuthRegistry) {    let mut flows = registry.write().await;    flows.retain(|_, flow| flow.created_at.elapsed() < OAUTH_FLOW_EXPIRY);}// ── Platform routing helpers ────────────────────────────────────────/// Prepend instance name to CSRF state for platform routing.////// The NEAR AI platform nginx proxy at `auth.DOMAIN` parses the instance name/// from the `state` query parameter (format: `instance:nonce`) to route the/// OAuth callback to the correct container.////// Returns the nonce unchanged when `IRONCLAW_INSTANCE_NAME` is not set/// (local/non-platform mode).pub fn build_platform_state(nonce: &str) -> String {    let instance = std::env::var("IRONCLAW_INSTANCE_NAME")        .or_else(|_| std::env::var("OPENCLAW_INSTANCE_NAME"))        .ok()        .filter(|v| !v.is_empty());    match instance {        Some(name) => format!("{}:{}", name, nonce),        None => nonce.to_string(),    }}/// Strip the instance prefix from a state parameter to recover the lookup nonce.////// `"myinstance:abc123"` → `"abc123"`, `"abc123"` → `"abc123"` (no prefix).////// Safe because nonces are base64url-encoded (`[A-Za-z0-9_-]`, no colons).pub fn strip_instance_prefix(state: &str) -> &str {    state        .split_once(':')        .map(|(_, nonce)| nonce)        .unwrap_or(state)}/// Exchange an OAuth authorization code via the platform's token exchange proxy.////// The proxy holds `client_secret` server-side so the container never sees it./// Authenticated via the gateway auth token (Bearer header).////// The proxy expects form params `{code, redirect_uri, code_verifier}` and
/// returns a standard Google token response `{access_token, refresh_token, expires_in}`.